 *
 * scan(source) returns an array of tokens: { kind, line, col, text }.
 * kind is one of 'ident', 'keyword', 'number', 'punct', 'rawstring', 'string'.
 * text is the source text for ident/keyword/number/punct tokens, and the
 * JSON-quoted decoded value for string/rawstring tokens.
 *
 * On a lexical error it throws a LexError with { line, col, message }.
 */

export class LexError extends Error {
  constructor(line, col, message) {
    super(message)
    this.line = line
    this.col = col
    this.reason = message
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const ONE_CHAR_PUNCT = new Set([
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
])

function isLetter(ch) {
  return ch !== undefined && /^\p{L}$/u.test(ch)
}
function isDecDigit(ch) {
  return ch !== undefined && ch >= '0' && ch <= '9'
}
function isHexDigit(ch) {
  return ch !== undefined && /^[0-9a-fA-F]$/.test(ch)
}
function isBinDigit(ch) {
  return ch === '0' || ch === '1'
}
function isOctDigit(ch) {
  return ch !== undefined && ch >= '0' && ch <= '7'
}
function isIdentStart(ch) {
  return isLetter(ch) || ch === '_'
}
function isIdentContinue(ch) {
  return isLetter(ch) || isDecDigit(ch) || ch === '_'
}
function isTrailingInvalid(ch) {
  return isLetter(ch) || isDecDigit(ch) || ch === '_'
}

export function scan(source) {
  const cps = Array.from(source)
  const n = cps.length
  let i = 0
  let line = 1
  let col = 1

  function peek(offset = 0) {
    return cps[i + offset]
  }
  function atEnd(offset = 0) {
    return i + offset >= n
  }
  function fail(l, c, message) {
    throw new LexError(l, c, message)
  }
  function advance() {
    const ch = cps[i]
    i++
    if (ch === '\n') {
      line++
      col = 1
    } else if (ch === '\t') {
      col = (Math.floor((col - 1) / 4) + 1) * 4 + 1
    } else {
      col++
    }
    return ch
  }

  function skipLineComment() {
    advance() // '/'
    advance() // '/'
    while (!atEnd() && peek() !== '\n') advance()
  }

  function skipBlockComment() {
    const startLine = line
    const startCol = col
    advance() // '/'
    advance() // '*'
    let depth = 1
    while (depth > 0) {
      if (atEnd()) fail(startLine, startCol, 'unterminated block comment')
      if (peek() === '/' && peek(1) === '*') {
        advance()
        advance()
        depth++
      } else if (peek() === '*' && peek(1) === '/') {
        advance()
        advance()
        depth--
      } else {
        advance()
      }
    }
  }

  function skipTrivia() {
    while (true) {
      if (atEnd()) return
      const ch = peek()
      if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') {
        advance()
        continue
      }
      if (ch === '/' && peek(1) === '/') {
        skipLineComment()
        continue
      }
      if (ch === '/' && peek(1) === '*') {
        skipBlockComment()
        continue
      }
      return
    }
  }

  function scanIdent() {
    const startLine = line
    const startCol = col
    const startIndex = i
    advance()
    while (!atEnd() && isIdentContinue(peek())) advance()
    const text = cps.slice(startIndex, i).join('')
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { kind, line: startLine, col: startCol, text }
  }

  function consumeDigitRun(isDigit) {
    while (true) {
      if (!atEnd() && isDigit(peek())) {
        advance()
        continue
      }
      if (!atEnd() && peek() === '_' && !atEnd(1) && isDigit(peek(1))) {
        advance()
        continue
      }
      break
    }
  }

  function scanNumber() {
    const startLine = line
    const startCol = col
    const startIndex = i
    let errored = false

    const first = peek()
    const second = peek(1)
    if (first === '0' && second !== undefined && /[xXbBoO]/.test(second)) {
      const p = second.toLowerCase()
      advance() // '0'
      advance() // prefix letter
      const isDigit = p === 'x' ? isHexDigit : p === 'b' ? isBinDigit : isOctDigit
      if (!atEnd() && isDigit(peek())) {
        advance()
        consumeDigitRun(isDigit)
      } else {
        errored = true
      }
    } else {
      advance() // first decimal digit
      consumeDigitRun(isDecDigit)
      if (!atEnd() && peek() === '.' && !atEnd(1) && isDecDigit(peek(1))) {
        advance() // '.'
        advance() // first fractional digit
        consumeDigitRun(isDecDigit)
      }
      if (!atEnd() && /[eE]/.test(peek())) {
        const hasSign = !atEnd(1) && /[+-]/.test(peek(1))
        const digitOffset = hasSign ? 2 : 1
        if (!atEnd(digitOffset) && isDecDigit(peek(digitOffset))) {
          advance() // e/E
          if (hasSign) advance() // sign
          advance() // first exponent digit
          consumeDigitRun(isDecDigit)
        }
      }
    }

    if (!atEnd() && isTrailingInvalid(peek())) errored = true

    if (errored) {
      while (!atEnd() && isTrailingInvalid(peek())) advance()
      const text = cps.slice(startIndex, i).join('')
      fail(startLine, startCol, `invalid number ${text}`)
    }

    const text = cps.slice(startIndex, i).join('')
    return { kind: 'number', line: startLine, col: startCol, text }
  }

  function scanString() {
    const startLine = line
    const startCol = col
    advance() // opening quote
    let value = ''
    while (true) {
      if (atEnd()) fail(startLine, startCol, 'unterminated string')
      const ch = peek()
      if (ch === '"') {
        advance()
        break
      }
      if (ch === '\n') fail(line, col, 'newline in string')
      if (ch === '\\') {
        const bsLine = line
        const bsCol = col
        advance() // backslash
        if (atEnd()) fail(startLine, startCol, 'unterminated string')
        const esc = peek()
        if (esc === 'n') {
          value += '\n'
          advance()
        } else if (esc === 't') {
          value += '\t'
          advance()
        } else if (esc === 'r') {
          value += '\r'
          advance()
        } else if (esc === '\\') {
          value += '\\'
          advance()
        } else if (esc === '"') {
          value += '"'
          advance()
        } else if (esc === '0') {
          value += '\0'
          advance()
        } else if (esc === 'x') {
          advance() // 'x'
          let hex = ''
          for (let k = 0; k < 2; k++) {
            if (atEnd()) fail(startLine, startCol, 'unterminated string')
            if (!isHexDigit(peek())) fail(bsLine, bsCol, 'invalid escape \\x')
            hex += peek()
            advance()
          }
          value += String.fromCharCode(parseInt(hex, 16))
        } else if (esc === 'u') {
          advance() // 'u'
          if (atEnd()) fail(startLine, startCol, 'unterminated string')
          if (peek() !== '{') fail(bsLine, bsCol, 'invalid escape \\u')
          advance() // '{'
          let hex = ''
          while (!atEnd() && isHexDigit(peek())) {
            hex += peek()
            advance()
          }
          if (atEnd()) fail(startLine, startCol, 'unterminated string')
          if (hex.length === 0) fail(bsLine, bsCol, 'invalid escape \\u')
          if (peek() !== '}') fail(bsLine, bsCol, 'invalid escape \\u')
          advance() // '}'
          const cp = parseInt(hex, 16)
          if (cp > 0x10ffff) fail(bsLine, bsCol, 'invalid escape \\u')
          value += String.fromCodePoint(cp)
        } else {
          fail(bsLine, bsCol, `invalid escape \\${esc}`)
        }
        continue
      }
      value += ch
      advance()
    }
    return { kind: 'string', line: startLine, col: startCol, text: JSON.stringify(value) }
  }

  function scanRawString() {
    const startLine = line
    const startCol = col
    advance() // 'r'
    advance() // '"'
    let value = ''
    while (true) {
      if (atEnd()) fail(startLine, startCol, 'unterminated string')
      const ch = peek()
      if (ch === '"') {
        advance()
        break
      }
      value += ch
      advance()
    }
    return { kind: 'rawstring', line: startLine, col: startCol, text: JSON.stringify(value) }
  }

  function scanPunct() {
    const startLine = line
    const startCol = col
    const a = peek()
    const b = peek(1)
    if (a !== undefined && b !== undefined) {
      const two = a + b
      if (TWO_CHAR_PUNCT.includes(two)) {
        advance()
        advance()
        return { kind: 'punct', line: startLine, col: startCol, text: two }
      }
    }
    if (ONE_CHAR_PUNCT.has(a)) {
      advance()
      return { kind: 'punct', line: startLine, col: startCol, text: a }
    }
    fail(startLine, startCol, `unexpected character ${a}`)
  }

  const tokens = []
  while (true) {
    skipTrivia()
    if (atEnd()) break
    const ch = peek()
    let token
    if (ch === '"') {
      token = scanString()
    } else if (ch === 'r' && peek(1) === '"') {
      token = scanRawString()
    } else if (isIdentStart(ch)) {
      token = scanIdent()
    } else if (isDecDigit(ch)) {
      token = scanNumber()
    } else {
      token = scanPunct()
    }
    tokens.push(token)
  }
  return tokens
}
